    cancelNoteTool();closeCommandPalette();analyzerView=false;analyzerFrozen=false;analyzerFollowTrack=false;analyzerWasActive=false;project=emptyProject();project.bpm=120;project.loop=false;selectedTrack=7;selectedNotes.clear();selectedNote=-1;currentFile=File();lane()={{0,1,60,.8f}};project.patterns[0].length=4;undoStack.clear();redoStack.clear();dirty=false;publish();perform(stop);setSize(1180,800);resetLayout();showPane(mixerPane);selectedEffect=3;auto original=JSON::toString(projectToJson(project));auto rev=revision;
    auto draw=[&]{hits.clear();Image image(Image::RGB,getWidth(),getHeight(),true);Graphics g(image);paint(g);};auto event=[&](Point<float> p){auto t=Time::getCurrentTime();return MouseEvent(Desktop::getInstance().getMainMouseSource(),p,ModifierKeys(ModifierKeys::leftButtonModifier),1,0,0,0,0,this,this,t,p,t,1,false);};
    draw();auto open=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.pane==mixerPane&&h.action==analyzerOpen;});check(open!=hits.end(),"Mixer exposes a real Audio analyzer button");if(open!=hits.end()){auto click=event(open->rect.getCentre());mouseDown(click);mouseUp(click);}check(analyzerView&&activePane==effectsPane&&engine->analyzer.enabled.load()&&paneCount==15,"analyzer opens inside the existing effects window without adding a new workspace");
